private void xrLabel23_SummaryRowChanged(object sender, System.EventArgs e) {
  if (GetCurrentColumnValue("lloji").ToString() == "FK" || GetCurrentColumnValue("lloji").ToString() == "FF" || GetCurrentColumnValue("lloji").ToString() == "FKK" || GetCurrentColumnValue("lloji").ToString() == "FFK")
                    diferenca += Convert.ToDouble(GetCurrentColumnValue("VLERA"));
                else
                    diferenca -= Convert.ToDouble(GetCurrentColumnValue("VLERA"));
}

