int row = 0;
private void GroupHeader3_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e)
{ 
	if (row % 2 == 0)
 	GroupHeader3.Styles.Style = (DevExpress.XtraReports.UI.XRControlStyle)StyleSheet["PermbajtjaRaportEven"]; 
	else
 	GroupHeader3.Styles.Style = (DevExpress.XtraReports.UI.XRControlStyle)StyleSheet["PermbajtjaRaportOdd"]; 
	row++;
 }
